/**
 * Function: Test transactional observer updates
 *
 * @param nodeName Name for the node to update
 * @return bool Whether transactional update succeeded (no cycle created)
 */
bool test_transactional_update(const std::string& nodeName) {
    using namespace reaction;

    // 1. Create observer nodes
    auto nodeA = std::make_shared<TestTransactionalObserver>("NodeA");
    auto nodeB = std::make_shared<TestTransactionalObserver>("NodeB");
    auto nodeC = std::make_shared<TestTransactionalObserver>("NodeC");

    // 2. Get observer graph instance
    auto& graph = ObserverGraph::getInstance();

    // 3. Set up initial relationship: A -> B -> C
    nodeA->updateObservers(nodeB);
    nodeB->updateObservers(nodeC);

    // 4. Notify target and verify relationship works
    nodeC->valueChanged();
    if (!nodeA->wasChanged() || !nodeB->wasChanged()) {
        return false;
    }
    if (nodeA->getCallCount() != 1 || nodeB->getCallCount() != 1) {
        return false;
    }

    // 5. Reset observer for next test
    nodeA->reset();
    nodeB->reset();

    // 6. Attempt transactional update that would create cycle: A -> B -> C -> A
    bool cycleCaught = false;
    try {
        nodeC->updateObservers(nodeA); // This should throw DependencyCycleException
    } catch (const DependencyCycleException& e) {
        // 7. Catch cycle exception if thrown
        cycleCaught = true;
    }

    if (!cycleCaught) {
        return false; // Expected cycle exception was not thrown
    }

    // 8. Notify target again
    nodeC->reset();
    nodeC->valueChanged();

    // 9. Verify original relationship is preserved (A -> B -> C, no cycle)
    // After notification, A and B should be notified again, but not C (it's the origin)
    if (!nodeA->wasChanged() || !nodeB->wasChanged() || nodeC->wasChanged()) {
        return false;
    }

    // Verify call counts are correct
    if (nodeA->getCallCount() != 1 || nodeB->getCallCount() != 1) {
        return false;
    }

    // 10. Return success status
    return true;
}

}  // namespace test
