std::tuple<std::string, int, int> test_filter_trigger(double initialValue,
                                                      double firstUpdate,
                                                      double secondUpdate,
                                                      double diffThreshold,
                                                      double levelThreshold) {
    using namespace reaction;

    // 1. Create reactive variable
    auto sensor = var(initialValue);

    // 2. Create variables to track recomputation count and last processed value
    int recomputeCount = 0;
    double lastProcessedValue = 0.0;

    // 3. Create filter-triggered calculation
    auto status = calc([&recomputeCount, &lastProcessedValue, levelThreshold](double value) -> std::string {
        recomputeCount++;
        lastProcessedValue = value;
        return (value > levelThreshold) ? "HIGH" : "NORMAL";
    }, sensor);

    // 4. Apply filter
    status.filter([&sensor, diffThreshold](double currentValue, double previousValue) {
        return std::abs(currentValue - previousValue) >= diffThreshold;
    }, sensor, sensor); // Pass sensor twice to compare current and previous values

    // Initialize previous value tracking for the filter
    sensor.value(initialValue);

    // 5. Update sensor with first value
    int recomputeCountAfterFirst = 0;
    sensor.value(firstUpdate);
    recomputeCountAfterFirst = recomputeCount;

    // 6. Record recompute count after first update
    // (Already recorded above)

