    int recomputeCountAfterSecond = 0;
    sensor.value(secondUpdate);
    recomputeCountAfterSecond = recomputeCount;

    // 8. Record recompute count after second update
    // (Already recorded above)

    // 9. Get final status
    std::string finalStatus = status.get();

    // 10. Return final status and counts
    return std::make_tuple(finalStatus, recomputeCountAfterFirst, recomputeCountAfterSecond);
}

