    /// @brief Pre-increment operator (++var)
    template <typename T = Type>
        requires(IsVarExpr<Expr> && !ConstType<Type> && PreIncrementable<T>)
    React &operator++() {
        atomicIncrement(*getPtr());
        return *this;
