 * Hashes the internal 64-bit ID.
 */
template <>
struct hash<reaction::UniqueID> {
    size_t operator()(const reaction::UniqueID &uid) const noexcept {
        return std::hash<uint64_t>{}(uid.m_id);
    }
};

