            is_sbo_storage = false;
        } else {
            // For uninitialized default-constructed objects, destroy heap_ptr
            storage.heap_ptr.~unique_ptr<Type>();
        }
    }

protected:
    mutable ConditionalSharedMutex m_resourceMutex; ///< Thread-safe access mutex
};

