        bool expected = false;
        if (m_threadSafetyEnabled.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
            // Increment version to invalidate thread-local caches
            m_safetyVersion.fetch_add(1, std::memory_order_release);
