    // Expose whether this instance is using SBO
    [[nodiscard]] bool isUsingSBO() const noexcept {
        if constexpr (memory::SBOTraits<Type>::is_sbo_eligible) {
            return static_cast<const memory::SBOResource<Type> *>(this)->isUsingSBO();
        } else {
            return false;
        }
    }
};

