    return ValiditySnapshot{
        validBeforeClose,           // firstValidBeforeClose
        validAfterClose,            // firstValidAfterClose
        equalBeforeClose,           // copiesEqualBeforeClose
        equalAfterClose,            // copiesEqualAfterClose
        equalityCheckFailedAfterClose // equalityCheckFailedAfterClose
    };
}

