    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(sourceNode);
    graph.addNode(targetNode);

    // 4. Set up observer relationship
    graph.addObserver(targetNode, sourceNode);

    // 5. Trigger notification on source
