inline AtomicCompoundSnapshot test_atomic_compound_assign() {
    using namespace reaction;

    auto counter = var(2);

    int evaluationCount = 0;
    auto tracker = calc([&](int value) {
        ++evaluationCount;
        return value;
    }, counter);

