 *
 * @tparam T Type of the variable
 */
template <typename T>
class ScopedValue {
public:
    ScopedValue(T &target, T newValue)
        : ref_(target), old_(target) {
        ref_ = std::move(newValue);
    }

    ~ScopedValue() {
        ref_ = std::move(old_);
    }

