    using namespace reaction;

    // 1. Create reactive variables
    auto varA = var(a);
    auto varB = var(b);
    auto varC = var(c);

    // 2. Build sum expression: A + B
    auto sumExpr = make_binary_expr<AddOp>(varA, varB);
    auto sum = expr(sumExpr);

    // 3. Build negated expression: -(A + B)
    auto negatedExpr = make_unary_expr<NegOp>(sumExpr);
    auto negated = expr(negatedExpr);

    // 4. Build chained expression: -(A + B) * C
    auto chainedExpr = make_binary_expr<MulOp>(negatedExpr, varC);
    auto chained = expr(chainedExpr);

    // 5. Get initial expression values
    RawExpressionSnapshot snapshot;
    snapshot.initialSum = sum.get();
    snapshot.initialNegatedSum = negated.get();
    snapshot.initialChainedValue = chained.get();

    // 6. Update variables to trigger recomputation
    varA.value(10);  // Update A
    varC.value(3);   // Update C

    // 7. Get updated expression values
    snapshot.updatedSum = sum.get();
    snapshot.updatedNegatedSum = negated.get();
    snapshot.updatedChainedValue = chained.get();

    // 8. Return raw expression snapshot
    return snapshot;
}

}  // namespace test
